/* READ ONLY Teradata SQL Assistant. Run each numbered SELECT separately.
Full populations, no account sample; no permanent tables/config/run changes.
Uses the analyst-confirmed numeric special list. Counts are account-month events.
Keep the source fixed and reconcile baseline counts to saved results first.
FLOAT casts precede arithmetic. NULL numeric outputs indicate invalid source grain;
absence of rows is not a pass. No individual account results should be uploaded.
*/
/* Month selection is intentionally discontinuous: triples only count if actual month gaps equal 1. */
WITH src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,EXTRACT(YEAR FROM FACT_DT)*12+EXTRACT(MONTH FROM FACT_DT) AS MK,COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC,CAST(CUST_ALL_C_PYMTS_CR_AVG_L6M_AMT AS FLOAT) AS CUST_ALL_C_PYMTS_CR_AVG_L6M_AMT,CAST(CHQ_LMT_UTIL_AVG_BAL_6M AS FLOAT) AS CHQ_LMT_UTIL_AVG_BAL_6M,CAST(CUST_ALL_MT_MAX_DELINQ_BASE_RT AS FLOAT) AS CUST_ALL_MT_MAX_DELINQ_BASE_RT,CAST(MV_PCKG_REPAY_TO_INC_RT AS FLOAT) AS MV_PCKG_REPAY_TO_INC_RT,CAST(PCKG_REPAY_AMT AS FLOAT) AS PCKG_REPAY_AMT,CAST(MV_PCKG_SAV_DEP_TO_BALANCE_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_BALANCE_RT,CAST(MV_PCKG_SAV_DEP_TO_REPAY_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_REPAY_RT FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE CAST(FACT_DT AS DATE) IN (DATE '2005-11-30',DATE '2005-12-31',DATE '2006-01-31',DATE '2006-02-28',DATE '2006-03-31',DATE '2007-10-31',DATE '2007-11-30',DATE '2007-12-31',DATE '2008-05-31',DATE '2008-06-30',DATE '2008-07-31')), vals AS (SELECT CAST('CUST_ALL_C_PYMTS_CR_AVG_L6M_AMT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,CUST_ALL_C_PYMTS_CR_AVG_L6M_AMT AS V FROM src UNION ALL SELECT CAST('CHQ_LMT_UTIL_AVG_BAL_6M' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,CHQ_LMT_UTIL_AVG_BAL_6M AS V FROM src UNION ALL SELECT CAST('CUST_ALL_MT_MAX_DELINQ_BASE_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,CUST_ALL_MT_MAX_DELINQ_BASE_RT AS V FROM src UNION ALL SELECT CAST('MV_PCKG_REPAY_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_REPAY_TO_INC_RT AS V FROM src UNION ALL SELECT CAST('PCKG_REPAY_AMT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,PCKG_REPAY_AMT AS V FROM src UNION ALL SELECT CAST('MV_PCKG_SAV_DEP_TO_BALANCE_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_SAV_DEP_TO_BALANCE_RT AS V FROM src UNION ALL SELECT CAST('MV_PCKG_SAV_DEP_TO_REPAY_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_SAV_DEP_TO_REPAY_RT AS V FROM src), st AS (SELECT F.*,CASE WHEN V IS NULL THEN 'MISSING' WHEN V IN (-99999,-999999,-999998,-99998,-99997,-9999,-9998,-999997,-999993,-999,-999995,999999,999998,999990,99999,99998,999.99,999.88,999,9999,9998) THEN 'SPECIAL' ELSE 'VALID' END AS VS FROM vals F),
h AS (SELECT S.*,LAG(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PS,LEAD(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS NS,LAG(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PM,LEAD(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS NM FROM st S), ctl AS (SELECT SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src)
SELECT FIELD_NAME,POU_DT,
 CASE WHEN MAX(BAD)=0 THEN COUNT(*) END AS TOTAL_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN VS='MISSING' THEN 1 ELSE 0 END) END AS MISSING_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN VS='SPECIAL' THEN 1 ELSE 0 END) END AS SPECIAL_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN VS='VALID' AND V=0 THEN 1 ELSE 0 END) END AS ZERO_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN VS='VALID' AND V<>0 THEN 1 ELSE 0 END) END AS VALID_NONZERO_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN MK-PM=1 AND PS='VALID' AND VS='VALID' THEN 1 ELSE 0 END) END AS VALID_PAIR_COUNT,
 CASE WHEN MAX(BAD)=0 THEN  SUM(CASE WHEN MK-PM=1 AND NM-MK=1 AND PS='VALID' AND VS='VALID' AND NS='VALID' THEN 1 ELSE 0 END) END AS VALID_TRIPLE_COUNT
FROM h CROSS JOIN ctl GROUP BY FIELD_NAME,POU_DT ORDER BY FIELD_NAME,POU_DT;
